script:
# Wide Motion
# How it sounds: Opposite-phase AM L/R for width.
# a Rate: 0.08 to 2.5, default 0.35
# b Depth: 0.15 to 0.7, default 0.42
# c Drive: 1 to 2.6, default 1.45

param a = Rate [0.08, 2.5]
param b = Depth [0.15, 0.7]
param c = Drive [1.0, 2.6]
osc1: shape = sine; freq = a; depth = 1.0  # LFO
split1: type = leftright {
  left {
    stage1: y = tube(x, c) * (1.0 - b + b * (0.5 + 0.5 * osc1))  # tube saturation
  }
  right {
    stage2: y = tube(x, c) * (1.0 - b + b * (0.5 - 0.5 * osc1))  # tube saturation
  }
}
